log-activity.message:
function retornaMSG() {
                
                var MSG;
                if(flowdata.get('Start/request_form/Acao') ==
                'false') MSG = "Ação / Action: Bloquear usuário
                / Lock User.";
                else MSG = "Ação / Action: Desbloquear usuário /
                Unlock User."
                
                return MSG;
                }
                retornaMSG();

